-- 食材按挂号的字典表方式保存：编号、中文名、分类、逻辑删除。
-- 不再保存英文原名，也不再使用 usda 编号把食材、别名和成分串起来。
-- 成分挂在食材编号上。没有的营养素不插行，读取时不能当成 0。

DROP TABLE IF EXISTS food_nutrient;
DROP TABLE IF EXISTS food_alias;
DROP TABLE IF EXISTS food_item;
DROP TABLE IF EXISTS food_category;

CREATE TABLE food_category (
    code         INT          NOT NULL COMMENT '分类编号。启用后不要改号',
    name         VARCHAR(32)  NOT NULL COMMENT '中文分类名',
    enabled      TINYINT      NOT NULL DEFAULT 1 COMMENT '1才可配餐',
    sort_no      INT          NOT NULL DEFAULT 0 COMMENT '展示顺序',
    remark       VARCHAR(400) NULL     COMMENT '备注',
    created_by   VARCHAR(100) NULL     COMMENT '创建人',
    updated_by   VARCHAR(100) NULL     COMMENT '修改人',
    created_at   DATETIME(3)  NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT '创建时间',
    updated_at   DATETIME(3)  NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3) COMMENT '更新时间',
    is_deleted   BIGINT       NOT NULL DEFAULT 0 COMMENT '删除标记。0未删除',
    PRIMARY KEY (code)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='食材分类';

CREATE TABLE food (
    id             BIGINT       NOT NULL AUTO_INCREMENT COMMENT '食材编号',
    name           VARCHAR(100) NOT NULL COMMENT '中文名',
    category_code  INT          NOT NULL COMMENT '分类编号',
    remark         VARCHAR(400) NULL     COMMENT '备注',
    created_by     VARCHAR(100) NULL     COMMENT '创建人',
    updated_by     VARCHAR(100) NULL     COMMENT '修改人',
    created_at     DATETIME(3)  NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT '创建时间',
    updated_at     DATETIME(3)  NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3) COMMENT '更新时间',
    is_deleted     BIGINT       NOT NULL DEFAULT 0 COMMENT '删除标记。0未删除；删除后写入非0，中文名可再用',
    PRIMARY KEY (id),
    UNIQUE KEY uk_food_name (name, is_deleted),
    KEY idx_food_category (category_code, is_deleted)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='食材。一行一种，按中文名识别';

CREATE TABLE food_nutrient (
    food_id        BIGINT         NOT NULL COMMENT '食材编号',
    nutrient_code  TINYINT        NOT NULL COMMENT '营养素。1能量 2蛋白质 3碳水化合物 4脂肪 5膳食纤维 6钠 7钾 8磷 9胆固醇 10饱和脂肪',
    amount         DECIMAL(18, 7) NOT NULL COMMENT '每100克含量。能量为千卡，钠钾磷胆固醇为毫克，其余为克',
    remark         VARCHAR(400)   NULL     COMMENT '备注',
    created_by     VARCHAR(100)   NULL     COMMENT '创建人',
    updated_by     VARCHAR(100)   NULL     COMMENT '修改人',
    created_at     DATETIME(3)    NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT '创建时间',
    updated_at     DATETIME(3)    NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3) COMMENT '更新时间',
    is_deleted     BIGINT         NOT NULL DEFAULT 0 COMMENT '删除标记。0未删除',
    PRIMARY KEY (food_id, nutrient_code, is_deleted)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='食材成分。没有行表示不知道，不能当成0';






















































































































































































